import { DomainError } from "../domain/DomainError";
import { ProjectRepository, TaskRepository } from "../domain/Repositories";
import { TaskStatus } from "../domain/TaskStatus";
import { TaskDto, toTaskDto } from "./TaskDtos";

export class ListProjectTasksUseCase {
  public constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
  ) {}

  public execute(projectId: string, status?: TaskStatus, assigneeId?: string): TaskDto[] {
    if (!this.projects.findById(projectId)) {
      throw new DomainError("Project does not exist");
    }
    return this.tasks.findByProject(projectId, status, assigneeId).map(toTaskDto);
  }
}

